// The HTTP Request node already emits one item per row for a JSON-array
// response. Just drop the empty-response case (no `id`) and pass the rest.
return $input.all().filter(i => i.json && i.json.id).map(i => ({ json: i.json }));

const response = $json;
const bp = $('Build Prompt').item.json;
let text;
try { text = response.candidates[0].content.parts[0].text; }
catch (e) { throw new Error('Gemini response format unexpected: ' + JSON.stringify(response).slice(0,300)); }
let cleaned = text.trim();
if (cleaned.startsWith('```')) cleaned = cleaned.replace(/^```(?:json)?\n?/, '').replace(/\n?```$/, '').trim();
let ex;
try { ex = JSON.parse(cleaned); }
catch (e) { throw new Error('Failed to parse Gemini output as JSON: ' + cleaned.slice(0,200)); }
const crypto = require('crypto');
const key = crypto.createHash('sha256').update(`${ex.vendor_name||''}|${ex.invoice_number||''}|${ex.total||0}`).digest('hex');
return { json: {
  invoiceId: bp.invoiceId,
  source_file_url: bp.source_file_url,
  vendor_name: ex.vendor_name ?? null,
  invoice_number: ex.invoice_number ?? null,
  invoice_date: ex.invoice_date ?? null,
  currency: ex.currency ?? null,
  subtotal: ex.subtotal ?? null,
  tax: ex.tax ?? null,
  total: ex.total ?? null,
  line_items: ex.line_items ?? null,
  extraction_confidence: ex.extraction_confidence ?? 0.5,
  idempotency_key: key
} };
